tool_input.content:
const root = process.argv[2];
const { handle } = await import(`${root}/src/api.js`);
const { tick } = await import(`${root}/src/scheduler.js`);
const { reset } = await import(`${root}/src/db.js`);

for (const [label, off] of [['IST +330', 330], ['UTC 0', 0], ['EST -300', -300]]) {
  reset();
  const { body } = handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: off } });
  let firedAt = null;
  for (let t = Date.parse('2026-02-28T12:00:00Z'); t < Date.parse('2026-03-02T12:00:00Z'); t += 60_000) {
    const lines = [];
    await tick(t, { formatter: 'format', out: (l) => lines.push(l) });
    if (lines.length) { firedAt = new Date(t).toISOString(); break; }
  }
  console.log(`${label}: should fire ${new Date(body.due_ms).toISOString()}, fired ${firedAt}`);
}

reset();
handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'call mum', at: '2026-03-01T09:00' } });
await tick(Date.parse('2026-03-02T00:00:00Z'), { formatter: 'legacy' });

reset();
const r = handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'x', at: '2026-03-01T09:00:00' } });
console.log('at with seconds -> status', r.status, 'due_ms', r.body.due_ms);
